// Generated by /ship test coverage audit.
// Value: protects=Sparkline draws finite SVG coordinates for single-point and flat series and exposes the text summary;
//   fails_when=the span||1 or single-point x guard is removed, producing NaN/Infinity in path/polyline;
//   why_new=e2e only checks the caption on 7 varied points; seam=none
import { cleanup, render } from '@testing-library/react';
import { afterEach, describe, expect, it } from 'vitest';
import Sparkline from './Sparkline';

const coords = (container: HTMLElement) =>
  [container.querySelector('path')!.getAttribute('d')!, container.querySelector('polyline')!.getAttribute('points')!].join(' ');

describe('Sparkline', () => {
  afterEach(cleanup);

  it.each([
    ['single point', [{ label: 'Mon', value: 42 }]],
    ['flat series', [{ label: 'Mon', value: 5 }, { label: 'Tue', value: 5 }, { label: 'Wed', value: 5 }]],
    ['varied series', [{ label: 'Mon', value: 1 }, { label: 'Tue', value: 9 }, { label: 'Wed', value: 4 }]],
  ])('%s renders finite coordinates', (_name, data) => {
    const { container, getByText } = render(<Sparkline data={data} summary="Sales summary" />);
    expect(coords(container)).not.toMatch(/NaN|Infinity/);
    for (const x of container.querySelectorAll('text')) expect(Number(x.getAttribute('x'))).not.toBeNaN();
    expect(container.querySelectorAll('text')).toHaveLength(data.length);
    expect(getByText('Sales summary').tagName).toBe('FIGCAPTION');
  });

  it('renders only the text summary for an empty series', () => {
    const { container, getByText } = render(<Sparkline data={[]} summary="No sales yet" />);
    expect(container.querySelector('svg')).toBeNull();
    expect(getByText('No sales yet')).toBeTruthy();
  });
});
